// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, uint256 callValue, uint256 priorFunding) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(callValue < type(uint256).max / 2);
        vm.assume(priorFunding < type(uint256).max / 2);
        vm.assume(callValue < priorFunding);

        vm.deal(address(c), priorFunding);
        uint256 balBefore = address(c).balance;

        vm.deal(address(this), callValue);
        try c.multiplicate{value: callValue}(adr) {}
        catch {}

        uint256 balAfter = address(c).balance;
        assertTrue(balAfter >= balBefore);
    }
}
